  const won = isWon(view.game);
  const selectionKind = view.game.selection.kind;
  useEffect(() => {
    if (!visible || view.paused || !view.game.started || won) return;
    let cancelled = false;
    let timer: number;
    const schedule = () => {
      timer = window.setTimeout(() => {
        if (cancelled) return;
        session.tick();
        schedule();
      }, session.nextDelay());
    };
    schedule();
    return () => { cancelled = true; window.clearTimeout(timer); };
