# Neon Pairs
Neon Pairs is a browser memory game that asks you to find every pair of matching cards.

Status: spec version 2.2.

Reveal two cards at a time and finish in as few moves as you can. A board code repeats a deal, so you can report a problem with the same starting cards.

## Play

Choose a size, then reveal a card and find its partner. Matches stay face up. A miss closes both cards after 800 active milliseconds. Finding every pair completes the game with your moves and time. New Game gives you another deal. Restart repeats the current deal. Full details are in [Rules](rules.md).

## Controls

Use mouse, touch or keyboard for the same card action. Keyboard movement, focus, card names and the screen reader journey are in [Input](input.md). The labels and behavior of game and reproduction actions are in [Controls](controls.md).

## Appearance

The game draws faces on a dark background. Shape, marker and fill distinguish each face without color. Layout, colors, motion, 16x16 behavior and zoom are in [Visuals](visuals.md). The game stays silent as defined in [Sound](sound.md).

## Repeat a game

A board code describes a deal. A snapshot saves progress. A replay records timed actions. The algorithms and version 1 formats are in [Reproducibility](reproducibility.md). Spec version 2.2 doesn't change those format versions.

## Build

Use React, TypeScript and native DOM controls. Package pins, commands and the offline HTML distribution are in [Technology](technology.md). Pure game functions, browser effects and behavior placement are in [Architecture](architecture.md).

Use the journeys in [Acceptance](acceptance.md) to check the finished game. Those examples add no rules beyond the requirement IDs in their defining documents.

## Out of scope

The game doesn't need to support these, so they're never tested:

- Keys and modifier combinations beyond the ones in [Input](input.md#keyboard-movement), which stay with the browser
- Holding a key down
- Several tabs or windows of the game open at once, where each tab may simply overwrite the saved preferences
- How a pointer press behaves when it drifts or is dragged off a card
- Replay or snapshot files with encodings beyond the stated rules, such as a byte-order mark
- Spoken screen-reader output, which stays part of user acceptance as [Input](input.md#screen-reader) describes
- Confirming that a touch long press on a real device opens the context menu without revealing a card, which stays part of user acceptance like spoken output because automated browsers can't produce that gesture

Back to [Play](#play).
import { useEffect, useState } from 'react';
import { isWon } from '../state.ts';
import { browserStorage, freshSeed } from './browser.ts';
import { GameSession } from './session.ts';
import type { SessionActions } from './sessionTypes.ts';

export function useGameSession() {
  const [session] = useState(() => new GameSession({ now: () => performance.now(), seed: freshSeed,
    storage: browserStorage(), visible: !document.hidden }));
  const [view, setView] = useState(session.getView);
  const [visible, setVisible] = useState(() => !document.hidden);
  const [actions] = useState<SessionActions>(() => ({ activate: session.activate, newGame: session.newGame,
    restart: session.restart, chooseSize: session.chooseSize, loadBoard: session.loadBoard,
    loadSnapshot: session.loadSnapshot, exportSnapshot: session.exportSnapshot, resume: session.resume }));

  useEffect(() => session.connect(setView), [session]);

  useEffect(() => {
    const onVisibility = () => {
      const shown = !document.hidden;
      session.setVisible(shown);
      setVisible(shown);
    };
    document.addEventListener('visibilitychange', onVisibility);
    onVisibility();
    return () => {
      document.removeEventListener('visibilitychange', onVisibility);
      session.setVisible(false);
    };
  }, [session]);

  const won = isWon(view.game);
  const selectionKind = view.game.selection.kind;
  useEffect(() => {
    if (!visible || view.paused || !view.game.started || won) return;
    let cancelled = false;
    let timer: number;
    const schedule = () => {
      timer = window.setTimeout(() => {
        if (cancelled) return;
        session.tick(view.revision);
        if (session.getView().revision === view.revision) schedule();
      }, session.nextDelay());
    };
    schedule();
    return () => { cancelled = true; window.clearTimeout(timer); };
  }, [session, view.revision, view.paused, view.game.started, selectionKind, visible, won]);

  return { view, actions };
}
import { boardCode } from '../boardCode.ts';
import type { Size } from '../boardCode.ts';
import { decodeSnapshot, encodeSnapshot } from '../snapshot.ts';
import { activateCard, advanceGame, createGame, isWon, MAX_ELAPSED_MS } from '../state.ts';
import type { GameState } from '../state.ts';
import { SessionClock } from './clock.ts';
import { readPreferences, writePreferences } from './storage.ts';
import type { Preferences } from './storage.ts';
import { turnResult } from './turnResult.ts';
import type { SessionActions, SessionEnvironment, SessionView } from './sessionTypes.ts';

function requireGame(code: string): GameState {
  const game = createGame(code);
  if (!game) throw new Error('Invalid session board');
  return game;
}

export class GameSession implements SessionActions {
  private view: SessionView;
  private preferences: Preferences;
  private visible: boolean;
  private readonly environment: SessionEnvironment;
  private readonly clock: SessionClock;
  private listener: ((view: SessionView) => void) | null = null;

  constructor(environment: SessionEnvironment) {
    this.environment = environment;
    this.clock = new SessionClock(environment.now);
    this.visible = environment.visible;
    this.preferences = readPreferences(environment.storage);
    const game = requireGame(boardCode(this.preferences.size, environment.seed(0)));
    this.view = { game, paused: false, revision: 0, best: this.preferences.bests[game.board.size] ?? null,
      announcement: { id: 0, text: '' }, status: '', celebrate: false };
  }

  getView = (): SessionView => this.view;

  connect = (listener: (view: SessionView) => void): (() => void) => {
    this.listener = listener;
    listener(this.view);
    return () => { this.listener = null; };
  };

  private emit(): void { this.listener?.(this.view); }

  private settle(): void {
    const milliseconds = this.clock.take();
    if (!this.visible || this.view.paused) return;
    const game = advanceGame(this.view.game, milliseconds);
    if (game !== this.view.game) this.view = { ...this.view, game };
  }

  tick = (expectedRevision = this.view.revision): void => {
    if (expectedRevision !== this.view.revision) return;
    this.settle();
    this.emit();
  };

  setVisible = (visible: boolean): void => {
    this.settle();
    this.visible = visible;
    this.emit();
  };

  nextDelay = (): number => {
    const { game } = this.view;
    const toSecond = game.elapsedMs < MAX_ELAPSED_MS ? 1000 - (game.elapsedMs % 1000) : 1000;
    return Math.max(1, Math.min(toSecond, game.selection.kind === 'mismatch' ? game.selection.remainingMs : 1000));
  };

  private announce(text: string): void {
    this.view = { ...this.view, announcement: { id: this.view.announcement.id + 1, text } };
  }

  activate = (index: number): void => {
    this.settle();
    if (!this.view.paused && this.visible) {
      const before = this.view.game;
      const game = activateCard(before, index);
      this.view = { ...this.view, game };
      if (before.selection.kind === 'one' && game !== before) {
        this.announce(turnResult(game));
        if (isWon(game)) {
          const best = this.preferences.bests[game.board.size];
          if (best === undefined || game.moves < best) {
            this.preferences = { ...this.preferences, bests: { ...this.preferences.bests, [game.board.size]: game.moves } };
            writePreferences(this.environment.storage, this.preferences);
            this.view = { ...this.view, best: game.moves };
          }
          this.view = { ...this.view, celebrate: true };
        }
      }
    }
    this.emit();
  };

  private replace(game: GameState, paused: boolean, status = ''): void {
    this.clock.take();
    this.preferences = { ...this.preferences, size: game.board.size };
    writePreferences(this.environment.storage, this.preferences);
    this.view = { game, paused, revision: this.view.revision + 1, best: this.preferences.bests[game.board.size] ?? null,
      announcement: { id: this.view.announcement.id + 1, text: status }, status, celebrate: false };
    this.emit();
  }

  newGame = (): void => {
    const { size, seed } = this.view.game.board;
    this.replace(requireGame(boardCode(size, this.environment.seed(seed))), false);
  };

  restart = (): void => { this.replace(requireGame(this.view.game.board.code), false); };

  chooseSize = (size: Size): void => {
    if (size === this.view.game.board.size) return;
    this.replace(requireGame(boardCode(size, this.environment.seed(this.view.game.board.seed))), false);
  };

  private invalid(status: string): false {
    this.view = { ...this.view, status };
    this.announce(status);
    this.emit();
    return false;
  }

  loadBoard = (text: string): boolean => {
    const game = createGame(text.trim());
    if (!game) return this.invalid('Invalid board code.');
    this.replace(game, false, 'Loaded board.');
    return true;
  };

  loadSnapshot = (text: string): boolean => {
    const game = decodeSnapshot(text);
    if (!game) return this.invalid('Invalid snapshot.');
    const complete = isWon(game);
    this.replace(game, !complete, complete ? 'Loaded completed snapshot.' : 'Loaded snapshot. Select Resume to continue.');
    return true;
  };

  exportSnapshot = (): string => {
    this.settle();
    this.emit();
    return encodeSnapshot(this.view.game);
  };

  resume = (): void => {
    if (!this.view.paused) return;
    this.settle();
    this.view = { ...this.view, paused: false };
    this.emit();
  };
}
