# Local preview

For the `portable` profile, selected whenever `SITES_MANAGED_LINUX_CONTAINER` is not `1`, including on Linux devices.

In a visible task with a user-facing preview tool, run the project's dev script or a static HTTP server (preferably with live reload) in a retained session after any required installation. Check that the representative page returns a successful HTTP response, then open the server's printed Local URL with `open_in_codex` or equivalent. Use supported forwarding when execution is remote; loopback on another host is not a device preview.

Reuse the server and Site tab through edits and publication. For a background task or an environment without user-facing preview, start a server only when needed for the work. Request network permissions when required for the server and its readiness check. Stop the owned server during final teardown.
import { useEffect, useState } from 'react';
import { isWon } from '../state.ts';
import { browserStorage, freshSeed } from './browser.ts';
import { GameSession } from './session.ts';
import type { SessionActions } from './sessionTypes.ts';

export function useGameSession() {
  const [session] = useState(() => new GameSession({ now: () => performance.now(), seed: freshSeed,
    storage: browserStorage(), visible: !document.hidden }));
  const [view, setView] = useState(session.getView);
  const [visible, setVisible] = useState(() => !document.hidden);
  const [actions] = useState<SessionActions>(() => ({ activate: session.activate, newGame: session.newGame,
    restart: session.restart, chooseSize: session.chooseSize, loadBoard: session.loadBoard,
    loadSnapshot: session.loadSnapshot, exportSnapshot: session.exportSnapshot, resume: session.resume }));

  useEffect(() => session.connect(setView), [session]);

  useEffect(() => {
    const onVisibility = () => {
      const shown = !document.hidden;
      session.setVisible(shown);
      setVisible(shown);
    };
    document.addEventListener('visibilitychange', onVisibility);
    onVisibility();
    return () => {
      document.removeEventListener('visibilitychange', onVisibility);
      session.setVisible(false);
    };
  }, [session]);

  const won = isWon(view.game);
  const selectionKind = view.game.selection.kind;
  useEffect(() => {
    if (!visible || view.paused || !view.game.started || won) return;
    let cancelled = false;
    let timer: number;
    const schedule = () => {
      timer = window.setTimeout(() => {
        if (cancelled) return;
        session.tick(view.revision);
        if (session.getView().revision === view.revision) schedule();
      }, session.nextDelay());
    };
    schedule();
    return () => { cancelled = true; window.clearTimeout(timer); };
  }, [session, view.revision, view.paused, view.game.started, selectionKind, visible, won]);

  return { view, actions };
}
import { useImperativeHandle, useRef, useState } from 'react';
import type { KeyboardEvent, Ref } from 'react';
import type { GameState } from '../state.ts';
import { Card } from './Card.tsx';
import { revealFocus } from './focus.ts';
import { arrowDestination } from './navigation.ts';
import './Board.css';

export interface BoardHandle { readonly focusRemembered: () => void }
interface BoardProps {
  readonly game: GameState;
  readonly onActivate: (index: number) => void;
  readonly ref?: Ref<BoardHandle>;
}

export function Board({ game, onActivate, ref }: BoardProps) {
  const [tabStop, setTabStop] = useState(0);
  const cards = useRef<(HTMLButtonElement | null)[]>([]);
  const area = useRef<HTMLDivElement | null>(null);
  useImperativeHandle(ref, () => ({ focusRemembered: () => cards.current[tabStop]?.focus() }), [tabStop]);
  const focus = (index: number, card: HTMLButtonElement) => {
    setTabStop(index);
    if (area.current) revealFocus(card, area.current);
  };
  const move = (event: KeyboardEvent<HTMLButtonElement>, index: number) => {
    if (event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return;
    const next = arrowDestination(index, game.board.size, event.key);
    if (next === null) return;
    event.preventDefault();
    cards.current[next]?.focus({ preventScroll: true });
  };
  const { size } = game.board;
  const selection = game.selection;
  return <div className="board-scroll" ref={area}>
    <div className="board-grid" role="group" aria-label={`${size} by ${size} card board`}
      style={{ gridTemplateColumns: `repeat(${size}, minmax(0, 1fr))`,
        minWidth: size * 44 + (size - 1) * 6, maxWidth: size * 88 + (size - 1) * 6 }}>
      {game.board.deck.map((face, index) => {
        const matched = game.matched.includes(index);
        const revealed = matched || (selection.kind === 'one' && selection.index === index)
          || (selection.kind === 'mismatch' && (selection.first === index || selection.second === index));
        return <Card key={index} index={index} size={size} face={revealed ? face : null}
          matched={matched} tabStop={index === tabStop} buttonRef={card => { cards.current[index] = card; }}
          onFocus={focus} onKeyDown={move} onActivate={onActivate} />;
      })}
    </div>
  </div>;
}
export function revealFocus(card: HTMLButtonElement, area: HTMLDivElement): void {
  card.scrollIntoView({ block: 'nearest', inline: 'nearest' });
  const target = card.getBoundingClientRect();
  const viewport = area.getBoundingClientRect();
  const left = viewport.left + area.clientLeft + 6;
  const top = viewport.top + area.clientTop + 6;
  const right = viewport.left + area.clientLeft + area.clientWidth - 6;
  const bottom = viewport.top + area.clientTop + area.clientHeight - 6;
  area.scrollLeft += target.left < left ? target.left - left : Math.max(0, target.right - right);
  area.scrollTop += target.top < top ? target.top - top : Math.max(0, target.bottom - bottom);
}
